"use strict";(globalThis.webpackChunklearngenomics_dev||=[]).push([[5361],{7400(e,n,t){t.r(n),t.d(n,{assets:()=>m,contentTitle:()=>c,default:()=>f,frontMatter:()=>l,metadata:()=>r,toc:()=>g});var s=t.cw((e,n)=>{const s=t.p+"assets/images/7.6-rna-lengths-dark-975140d83ad16e9f796d54cf5f0a3090.svg";t.d(n,["A",0,s])}),a=t.cw((e,n)=>{const s=t.p+"assets/images/7.7-microrna-path-dark-fa61a83b4a486415c24d6f4eac76a059.svg";t.d(n,["A",0,s])}),i=t.cw((e,n)=>{const s=t.p+"assets/images/7.6-rna-lengths-94e27fa56c6c605721d29c9a84fe4b1f.svg";t.d(n,["A",0,s])}),o=t.cw((e,n)=>{const s=t.p+"assets/images/7.7-microrna-path-b67a93f4dd7e9542f0ca304e73deb573.svg";t.d(n,["A",0,s])});const r=JSON.parse('{"id":"advanced-topics/non-coding-rnas","title":"Noncoding RNAs","description":"In [The Central","source":"@site/docs/07-advanced-topics/non-coding-rnas.md","sourceDirName":"07-advanced-topics","slug":"/advanced-topics/non-coding-rnas","permalink":"/docs/advanced-topics/non-coding-rnas","draft":false,"unlisted":false,"editUrl":"https://github.com/stjude/learngenomics.dev/tree/main/docs/07-advanced-topics/non-coding-rnas.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"title":"Noncoding RNAs","track":"Advanced Topics","sidebar_position":3},"sidebar":"tutorialSidebar","previous":{"title":"Epigenetic Modifications","permalink":"/docs/advanced-topics/epigenetic-modifications"},"next":{"title":"The Structure of DNA","permalink":"/docs/advanced-topics/dna-structure"}}');var h=t(4848),d=t(8453);const l={title:"Noncoding RNAs",track:"Advanced Topics",sidebar_position:3},c=void 0,m={},g=[{value:"The RNAs That Run the Cell",id:"the-rnas-that-run-the-cell",level:2},{value:"MicroRNAs",id:"micrornas",level:2},{value:"Long Noncoding RNAs",id:"long-noncoding-rnas",level:2},{value:"Measuring Them",id:"measuring-them",level:2},{value:"Noncoding RNAs in Cancer",id:"noncoding-rnas-in-cancer",level:2},{value:"MicroRNAs Lost in Leukemia",id:"micrornas-lost-in-leukemia",level:3},{value:"DICER1 and Childhood Tumors",id:"dicer1-and-childhood-tumors",level:3},{value:"A Spliceosome RNA in Medulloblastoma",id:"a-spliceosome-rna-in-medulloblastoma",level:3},{value:"Setting Up",id:"setting-up",level:2},{value:"Try It",id:"try-it",level:2}];function p(e){const n={a:"a",code:"code",em:"em",figcaption:"figcaption",figure:"figure",h2:"h2",h3:"h3",img:"img",li:"li",p:"p",pre:"pre",span:"span",strong:"strong",ul:"ul",...(0,d.R)(),...e.components};return(0,h.jsxs)(h.Fragment,{children:[(0,h.jsxs)(n.p,{children:["In ",(0,h.jsx)(n.a,{href:"/docs/biological-foundations/the-central-dogma#from-dna-to-protein",children:"The Central\nDogma"}),", genes\nare copied into RNA, and the RNA is translated into protein. Many RNAs skip the last\nstep and do their work as RNA. These noncoding RNAs are usually sorted by length. Those\nlonger than 200 nucleotides (nt) are called long noncoding RNAs, and the rest are called\nsmall (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/s41580-022-00566-8",children:"Mattick et al., 2023"}),"). As that\nreview notes, the cutoff was chosen arbitrarily, because 200 nt is a convenient size\nlimit in the lab methods used to purify RNA. ",(0,h.jsx)(n.a,{href:"#figure-7-6",children:"Figure 7.6"})," shows how long\neach kind usually is. This page covers the main kinds, how they're measured and how they\nturn up in cancer."]}),"\n",(0,h.jsxs)(n.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-7-6",children:[(0,h.jsx)(n.img,{alt:"A chart of RNA lengths on a log scale from 10 to 10,000 nucleotides. A dashed line at 200 nucleotides divides a shaded side labeled small from a side labeled long. Rows from top: microRNAs, a point at about 22; piRNAs, a bar from 21 to 35; tRNAs, a bar from 76 to 90; snoRNAs, a bar from 68 to 213 with a median of 118; snRNAs, a bar from 107 to 188; rRNAs, four points labeled 5S, 5.8S, 18S and 28S, at 119, 157, 1,869 and 5,070; lncRNAs, a bar from 369 to 2,264 with a median of 813; and, for comparison, mRNAs, a bar from 760 to 9,142 with a median of 2,941. A key identifies a bar as the typical range and a dot on a bar as the median.",src:i().A+"",width:"392",height:"413"}),(0,h.jsx)(n.img,{className:"lg-figure__dark",src:s().A,alt:"A chart of RNA lengths on a log scale from 10 to 10,000 nucleotides. A dashed line at 200 nucleotides divides a shaded side labeled small from a side labeled long. Rows from top: microRNAs, a point at about 22; piRNAs, a bar from 21 to 35; tRNAs, a bar from 76 to 90; snoRNAs, a bar from 68 to 213 with a median of 118; snRNAs, a bar from 107 to 188; rRNAs, four points labeled 5S, 5.8S, 18S and 28S, at 119, 157, 1,869 and 5,070; lncRNAs, a bar from 369 to 2,264 with a median of 813; and, for comparison, mRNAs, a bar from 760 to 9,142 with a median of 2,941. A key identifies a bar as the typical range and a dot on a bar as the median.",width:"392",height:"413",loading:"lazy",decoding:"async"}),(0,h.jsxs)(n.figcaption,{children:[(0,h.jsx)(n.span,{className:"lg-figure__number",children:"Figure 7.6"})," How long noncoding RNAs are, with mRNAs for comparison. MicroRNAs, piRNAs and tRNAs fall below 200 nucleotides, snoRNAs and rRNAs span that line, and most long noncoding RNAs are shorter than most mRNAs. For snoRNAs, lncRNAs and mRNAs, the bar covers the middle 90% of transcripts in GENCODE release 50, with mRNAs limited to one transcript per gene. The snRNA bar spans the five spliceosome snRNAs in GENCODE, and the rRNA lengths are from RefSeq."]})]}),"\n",(0,h.jsx)(n.h2,{id:"the-rnas-that-run-the-cell",children:"The RNAs That Run the Cell"}),"\n",(0,h.jsx)(n.p,{children:"Some noncoding RNAs are part of the basic machinery that every cell needs."}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.strong,{children:"Ribosomal RNA (rRNA)"})," makes up most of a cell's RNA, which is why RNA-seq ",(0,h.jsx)(n.a,{href:"/docs/next-generation-sequencing/types-of-sequencing/rna-seq#how-the-library-is-made",children:"removes it\nfirst"}),".\nA human ribosome is built from two subunits and four rRNAs. The small subunit holds the\n18S rRNA, and the large subunit holds the 28S, 5.8S and 5S rRNAs. The 18S, 5.8S and 28S\nrRNAs are all cut from one long precursor RNA, and 5S is made from separate genes\n(",(0,h.jsx)(n.a,{href:"https://doi.org/10.1002/wrna.1269",children:"Henras et al., 2015"}),"). The rRNA does more than hold\nthe ribosome together. When the structure of the large subunit was solved in a microbe\nthat lives in very salty water, the spot where amino acids are joined into a protein\nturned out to be made entirely of RNA, with no protein within about 18 \xe5ngstr\xf6ms\n(",(0,h.jsx)(n.a,{href:"https://doi.org/10.1126/science.289.5481.920",children:"Nissen et al., 2000"}),"). An RNA that\nspeeds up a chemical reaction is called a ",(0,h.jsx)(n.strong,{children:"ribozyme"}),", and the ribosome is one."]}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.a,{href:"/docs/biological-foundations/translation#decoding-the-transcript",children:"Transfer RNAs"}),"\nbring each amino acid to the ribosome. Most are 76 to 90 nt long (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1080/15476286.2020.1809197",children:"Berg and Brandl,\n2021"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.strong,{children:"Small nuclear RNAs (snRNAs)"})," are the RNA inside the\n",(0,h.jsx)(n.a,{href:"/docs/advanced-topics/alternative-splicing#how-splice-sites-are-chosen",children:"spliceosome"}),". The main spliceosome\nis assembled from five snRNAs, U1, U2, U4, U5 and U6, each bound to proteins, with U4\nand U6 paired together. The snRNAs find the splice sites partly by pairing with them.\nOne of the first steps in splicing is U1 snRNA pairing with the 5\u2032 splice site at the\nstart of an intron (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1101/cshperspect.a003707",children:"Will and L\xfchrmann,\n2011"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.strong,{children:"Small nucleolar RNAs (snoRNAs)"})," work in the nucleolus, the part of the nucleus where\nribosomes are built, as Henras et al. describe. Many of them help make small chemical\nchanges to other RNAs, mostly rRNAs and snRNAs. Each of these snoRNAs carries an enzyme\nto one spot on its target RNA, which it finds by pairing with the bases there. The\nenzyme then changes a single nucleotide at that spot. Some snoRNAs bring an enzyme that\nadds a ",(0,h.jsx)(n.a,{href:"/docs/advanced-topics/epigenetic-modifications#dna-methylation",children:"methyl group"}),". Others bring one\nthat turns a uridine into pseudouridine, a rearranged form of the same base (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1093/nar/gkz1140",children:"Bratkovi\u010d\net al., 2020"}),")."]}),"\n",(0,h.jsx)(n.h2,{id:"micrornas",children:"MicroRNAs"}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.strong,{children:"MicroRNAs"})," are about 22 nt long, and they turn down other genes by pairing with their\nmRNAs (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2018.03.006",children:"Bartel, 2018"}),"). Each one starts out\nas part of a much longer RNA that folds back on itself into a hairpin, and it takes two\ncuts to free it (",(0,h.jsx)(n.a,{href:"#figure-7-7",children:"Figure 7.7"}),"). In the nucleus, an enzyme called Drosha,\nworking with a partner protein called DGCR8, cuts the hairpin out of the long RNA. The\nhairpin, about 70 nt at this stage (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature01957",children:"Lee et al.,\n2003"}),"), is carried out to the cytoplasm, where an\nenzyme called ",(0,h.jsx)(n.strong,{children:"Dicer"})," cuts off the loop. That leaves a short double-stranded piece\nabout 20 base pairs long. One strand, the mature microRNA, is loaded into a protein\ncalled ",(0,h.jsx)(n.strong,{children:"Argonaute"}),", and the other strand is broken down."]}),"\n",(0,h.jsxs)(n.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-7-7",children:[(0,h.jsx)(n.img,{alt:"Four numbered steps, each a drawing of RNA. Step 1, In the nucleus, Drosha cuts the hairpin free: a long RNA with loose ends on the left folds back on itself into a paired stem that ends in a loop on the right. One side of the stem is highlighted as the microRNA and the other as its partner strand. Drosha cuts across the stem near the loose ends. Step 2, In the cytoplasm, Dicer cuts off the loop: the freed hairpin, its ends labeled 5\u2032 and 3\u2032, with Dicer cutting across the stem next to the loop. Step 3, Argonaute keeps one strand: the microRNA sits inside Argonaute, and the partner strand lies in pieces, labeled broken down. Step 4, The seed pairs with a site in an mRNA: an mRNA with a 5\u2032 cap, a coding sequence and a 3\u2032 UTR ending in AAAA, with Argonaute and its microRNA bound in the 3\u2032 UTR. A close-up shows the mRNA site, GCUGCU written 5\u2032 to 3\u2032, paired base by base with six letters of miR-16, which is written 3\u2032 to 5\u2032 as GCGGUUAUAAAUGCACGACGAU. The six paired letters, next to the microRNA's 5\u2032 end, are highlighted as the seed. A key identifies the microRNA, its partner strand, the rest of the RNA and proteins.",src:o().A+"",width:"392",height:"599"}),(0,h.jsx)(n.img,{className:"lg-figure__dark",src:a().A,alt:"Four numbered steps, each a drawing of RNA. Step 1, In the nucleus, Drosha cuts the hairpin free: a long RNA with loose ends on the left folds back on itself into a paired stem that ends in a loop on the right. One side of the stem is highlighted as the microRNA and the other as its partner strand. Drosha cuts across the stem near the loose ends. Step 2, In the cytoplasm, Dicer cuts off the loop: the freed hairpin, its ends labeled 5\u2032 and 3\u2032, with Dicer cutting across the stem next to the loop. Step 3, Argonaute keeps one strand: the microRNA sits inside Argonaute, and the partner strand lies in pieces, labeled broken down. Step 4, The seed pairs with a site in an mRNA: an mRNA with a 5\u2032 cap, a coding sequence and a 3\u2032 UTR ending in AAAA, with Argonaute and its microRNA bound in the 3\u2032 UTR. A close-up shows the mRNA site, GCUGCU written 5\u2032 to 3\u2032, paired base by base with six letters of miR-16, which is written 3\u2032 to 5\u2032 as GCGGUUAUAAAUGCACGACGAU. The six paired letters, next to the microRNA's 5\u2032 end, are highlighted as the seed. A key identifies the microRNA, its partner strand, the rest of the RNA and proteins.",width:"392",height:"599",loading:"lazy",decoding:"async"}),(0,h.jsxs)(n.figcaption,{children:[(0,h.jsx)(n.span,{className:"lg-figure__number",children:"Figure 7.7"})," How a microRNA is made and how it finds its targets. Drosha cuts the hairpin from a longer RNA in the nucleus, and Dicer cuts off its loop in the cytoplasm. Argonaute keeps one strand of what's left, the mature microRNA, and the other strand is broken down. The microRNA then guides Argonaute to mRNAs with a site that pairs with its seed, nucleotides 2 to 7, usually in the 3\u2032 UTR. The microRNA shown is miR-16, with its sequence from GRCh38. The mRNA site is drawn to match its seed and doesn't come from a particular gene."]})]}),"\n",(0,h.jsxs)(n.p,{children:["Inside Argonaute, the microRNA works as a guide. Its key part is the ",(0,h.jsx)(n.strong,{children:"seed"}),",\nnucleotides 2 to 7 counted from its 5\u2032 end, which pairs with matching sites in mRNAs,\nmostly in their ",(0,h.jsx)(n.a,{href:"/docs/biological-foundations/transcription#genomic-regions-and-transcription",children:"3\u2032\nUTRs"}),",\nas Bartel's review explains. Once Argonaute is bound, the mRNA makes less protein,\nmainly because the mRNA is broken down faster. In one study, lower mRNA levels accounted\nfor at least 84% of the drop in protein (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature09267",children:"Guo et al.,\n2010"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:["A six-letter seed can match many genes, so each microRNA has many targets. When a single\nmicroRNA was added to human cells, about 100 mRNAs dropped within 12 hours (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature03315",children:"Lim et al.,\n2005"}),"). Two studies that measured proteins directly\nfound that one microRNA lowered hundreds of proteins, most of them only a little\n(",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature07228",children:"Selbach et al., 2008"}),"; ",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature07242",children:"Baek et al.,\n2008"}),"). Across the genome, more than 60% of human\nprotein-coding genes have kept sites that pair with microRNAs over the course of\nevolution (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1101/gr.082701.108",children:"Friedman et al., 2009"}),"). MicroRNAs\nwith the same seed are grouped into a seed family, and members of a family often do\noverlapping jobs, as Bartel's review notes."]}),"\n",(0,h.jsxs)(n.p,{children:["A second group of small RNAs works the same way. ",(0,h.jsx)(n.strong,{children:"PIWI-interacting RNAs (piRNAs)"})," are\n21 to 35 nt long and guide PIWI proteins, a branch of the Argonaute family (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1186/gb-2008-9-2-210",children:"H\xf6ck and\nMeister, 2008"}),"). Their main job is in the germ\nline, the cells that give rise to eggs and sperm, where they silence transposons,\nstretches of DNA that can copy themselves into new places in the genome (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/s41576-018-0073-3",children:"Ozata et al.,\n2019"}),")."]}),"\n",(0,h.jsx)(n.h2,{id:"long-noncoding-rnas",children:"Long Noncoding RNAs"}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.strong,{children:"Long noncoding RNAs (lncRNAs)"})," are the biggest group. GENCODE lists more lncRNA genes\nthan protein-coding genes, as you'll see in Try It below. Most are made by the same RNA\npolymerase that makes mRNA, and many are spliced and given a 5\u2032 cap and a poly-A tail,\njust as mRNAs are, though some aren't, as Mattick's review notes. A few have\nwell-understood jobs:"]}),"\n",(0,h.jsxs)(n.ul,{children:["\n",(0,h.jsxs)(n.li,{children:[(0,h.jsx)(n.strong,{children:"XIST"})," silences one of the two X chromosomes in female cells, the X inactivation\nmentioned in ",(0,h.jsx)(n.a,{href:"/docs/advanced-topics/epigenetic-modifications#dna-methylation",children:"Epigenetic Modifications"}),".\nIt's made only from the X chromosome that will be silenced (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/349038a0",children:"Brown et al.,\n1991"}),"), it spreads along that same chromosome and\ncoats it (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1083/jcb.132.3.259",children:"Clemson et al., 1996"}),"), and X\ninactivation can't happen without it (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1371/journal.pgen.1008333",children:"Loda and Heard,\n2019"}),")."]}),"\n",(0,h.jsxs)(n.li,{children:[(0,h.jsx)(n.strong,{children:"NEAT1"})," is the scaffold of paraspeckles, small bodies in the nucleus (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.molcel.2009.01.026",children:"Clemson et\nal., 2009"}),"). Mice without NEAT1 live and\nbreed normally in the lab and lose only their paraspeckles (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1083/jcb.201011110",children:"Nakagawa et al.,\n2011"}),"), though a later study found that some of\nthe females fail to become pregnant (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1242/dev.110544",children:"Nakagawa et al.,\n2014"}),")."]}),"\n",(0,h.jsxs)(n.li,{children:[(0,h.jsx)(n.strong,{children:"Telomerase RNA"})," is part of\n",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/hallmarks-of-cancer#refusing-to-die",children:"telomerase"}),", the\nenzyme that rebuilds the ends of chromosomes. At 451 nt, it's long enough to count as\na lncRNA (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1042/BST20230269",children:"Klump and Schmidt, 2023"}),"). The core of\nthe enzyme is this RNA plus a protein called TERT (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/s41586-018-0062-x",children:"Nguyen et al.,\n2018"}),"). Eleven of its bases, CUAACCCUAAC,\nform the template that telomerase copies to add TTAGGG repeats to chromosome ends\n(",(0,h.jsx)(n.a,{href:"https://doi.org/10.1126/science.7544491",children:"Feng et al., 1995"}),")."]}),"\n"]}),"\n",(0,h.jsxs)(n.p,{children:["Most lncRNAs look quite different from mRNAs in sequencing data. They're usually made at\nlower levels and in fewer tissues, and their exons change faster over evolution than\nprotein-coding exons, though more slowly than old repeated DNA thought to have no\nfunction. Some of that tissue specificity may come from their low levels, which make\nthem easy to miss in tissues where they are made (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1101/gr.132159.111",children:"Derrien et al.,\n2012"}),"). In one catalog of lncRNAs found between\ngenes, 78% were specific to a tissue, against about 19% of protein-coding genes (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1101/gad.17446611",children:"Cabili\net al., 2011"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:["How many lncRNAs have a real job is still argued over. Mattick's review counts about\n50,000 papers on lncRNAs, more than 2,000 of them reporting a tested function, though\nmost of those functions haven't been followed up in detail. Others argue that most\nlncRNAs are noise from transcription or play only minor roles (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1146/annurev-genom-112921-123710",children:"Ponting and Haerty,\n2022"}),"). Sometimes a lncRNA gene\ndoes its job without needing the RNA at all. In a study of 12 lncRNA loci in mouse\ncells, 5 changed the activity of a neighboring gene, and none of those effects needed\nthe lncRNA. They came from the act of transcription, from splicing, or from the lncRNA's\npromoter acting like an enhancer (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature20149",children:"Engreitz et al.,\n2016"}),'). Even a skeptic\'s estimate leaves plenty to\nstudy. As Palazzo and Lee put it, "even if 10% of current lncRNAs prove to be\nfunctional, this would represent a wealth of new biology" (',(0,h.jsx)(n.a,{href:"https://doi.org/10.3389/fgene.2015.00002",children:"Palazzo and Lee,\n2015"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:["Splicing can also close an RNA into a loop. In ",(0,h.jsx)(n.strong,{children:"back-splicing"}),", the end of an exon is\njoined to the start of an earlier exon, making a ",(0,h.jsx)(n.strong,{children:"circular RNA"}),". With no free ends, a\ncircular RNA has no 5\u2032 cap or poly-A tail (",(0,h.jsx)(n.a,{href:"https://doi.org/10.15252/embj.2018100836",children:"Patop et al.,\n2019"}),")."]}),"\n",(0,h.jsx)(n.h2,{id:"measuring-them",children:"Measuring Them"}),"\n",(0,h.jsxs)(n.p,{children:["How a library is made decides which noncoding RNAs it can see. As\n",(0,h.jsx)(n.a,{href:"/docs/next-generation-sequencing/types-of-sequencing/rna-seq#how-the-library-is-made",children:"RNA-seq"}),"\ndescribes, poly-A selection loses RNAs without a tail, such as circular RNAs and some\nlncRNAs, and total RNA-seq keeps them."]}),"\n",(0,h.jsxs)(n.p,{children:["MicroRNAs and other very short RNAs need their own method. In standard RNA-seq, they're\ntoo short to be copied reliably and are lost when fragments are selected by size.\n",(0,h.jsx)(n.strong,{children:"Small RNA-seq"})," attaches adapters directly to both ends of each small RNA before\ncopying it into DNA (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1186/s13045-020-00945-8",children:"Sun and Chen, 2020"}),").\nSome kits add a poly-A tail to each small RNA in place of one adapter. Most start from\nall of a sample's RNA, and the short inserts are selected by size after the adapters are\nadded (",(0,h.jsx)(n.a,{href:"https://doi.org/10.3390/diagnostics11060964",children:"Benesova et al., 2021"}),")."]}),"\n",(0,h.jsx)(n.h2,{id:"noncoding-rnas-in-cancer",children:"Noncoding RNAs in Cancer"}),"\n",(0,h.jsx)(n.h3,{id:"micrornas-lost-in-leukemia",children:"MicroRNAs Lost in Leukemia"}),"\n",(0,h.jsxs)(n.p,{children:["Chronic lymphocytic leukemia (CLL) is a cancer of B cells, a type of white blood cell. A\nregion of chromosome 13 called 13q14 is deleted in more than half of CLL cases. Calin et\nal. found two microRNA genes in this region, ",(0,h.jsx)(n.em,{children:"MIR15A"})," and ",(0,h.jsx)(n.em,{children:"MIR16-1"}),", and found them\ndeleted or turned down in about 68% of cases (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1073/pnas.242606799",children:"Calin et al.,\n2002"}),"). Their microRNAs, miR-15a and miR-16,\nlower Bcl-2, a protein that keeps cells from dying, and restoring them made leukemia\ncells die in a lab model (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1073/pnas.0506654102",children:"Cimmino et al.,\n2005"}),"). Bcl-2 is the relative of Bcl-xL from\n",(0,h.jsx)(n.a,{href:"/docs/advanced-topics/alternative-splicing#why-it-matters",children:"Alternative Splicing"}),". Mice missing the stretch\nof 13q14 that holds both microRNAs developed the range of B cell disorders seen in human\nCLL, and losing the two microRNAs made B cells divide faster (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.ccr.2009.11.019",children:"Klein et al.,\n2010"}),")."]}),"\n",(0,h.jsx)(n.h3,{id:"dicer1-and-childhood-tumors",children:"DICER1 and Childhood Tumors"}),"\n",(0,h.jsxs)(n.p,{children:["Inherited loss-of-function variants in ",(0,h.jsx)(n.em,{children:"DICER1"}),", the gene for Dicer, predispose children\nto pleuropulmonary blastoma (PPB), a rare lung tumor. Hill et al. found them in 11\nfamilies with PPB (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1126/science.1174334",children:"Hill et al., 2009"}),"). The\ntumors follow the ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/inherited-risk#the-second-hit",children:"two-hit\npattern"})," in their own way. In\n15 tumors studied, every one had a variant that broke one copy of ",(0,h.jsx)(n.em,{children:"DICER1"}),", inherited in\n12 and acquired in the tumor in 3. Each also had an acquired change that swapped one\namino acid in one of Dicer's two cutting regions (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/onc.2014.150",children:"Pugh et al.,\n2014"}),"). People who inherit a ",(0,h.jsx)(n.em,{children:"DICER1"})," variant can\nalso develop other tumors, including Sertoli\u2013Leydig cell tumors of the ovary, cystic\nnephroma of the kidney and thyroid nodules. The risk is highest in early childhood, and\nthe variants are inherited in an autosomal dominant pattern with reduced\n",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/inherited-risk",children:"penetrance"}),", so many people who carry one\nnever develop a tumor (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1158/1078-0432.CCR-17-3089",children:"Schultz et al.,\n2018"}),")."]}),"\n",(0,h.jsx)(n.h3,{id:"a-spliceosome-rna-in-medulloblastoma",children:"A Spliceosome RNA in Medulloblastoma"}),"\n",(0,h.jsxs)(n.p,{children:["Medulloblastoma is a brain tumor, and one group of these tumors is named for the Sonic\nhedgehog (SHH) signaling pathway that drives them. About half of SHH medulloblastomas\ncarry the same mutation in U1 snRNA, an A changed to G at its third base. It's found in\n97% of adults with this kind of tumor and 25% of adolescents, but it's largely absent in\ninfants (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/s41586-019-1650-0",children:"Suzuki et al., 2019"}),"). That base\nsits in the part of U1 that pairs with the 5\u2032 splice site, so the mutant U1 picks out\nnew ",(0,h.jsx)(n.a,{href:"/docs/advanced-topics/alternative-splicing#when-splicing-goes-wrong",children:"cryptic splice sites"}),". As Suzuki\net al. found, the changed splicing switches off the ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#tumor-suppressors",children:"tumor\nsuppressor"}),"\n",(0,h.jsx)(n.em,{children:"PTCH1"})," and switches on the oncogenes ",(0,h.jsx)(n.em,{children:"GLI2"})," and ",(0,h.jsx)(n.em,{children:"CCND2"}),". A different change at the same\nbase, A to C, turns up in other cancers, including about 4% of CLL and about 6% of liver\ncancers (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/s41586-019-1651-z",children:"Shuai et al., 2019"}),"; ",(0,h.jsx)(n.a,{href:"https://doi.org/10.3390/cancers14020281",children:"Ni\xf1o et al.,\n2022"}),")."]}),"\n",(0,h.jsx)(n.h2,{id:"setting-up",children:"Setting Up"}),"\n",(0,h.jsxs)(n.p,{children:["This page uses ",(0,h.jsx)(n.code,{children:"samtools"})," and ",(0,h.jsx)(n.code,{children:"curl"}),", as in ",(0,h.jsx)(n.a,{href:"/docs/from-reads-to-variants/setting-up",children:"Setting\nUp"})," in From Reads to Variants. If you\nmade the ",(0,h.jsx)(n.code,{children:"reads-to-variants"})," or ",(0,h.jsx)(n.code,{children:"file-formats"})," environment, activate it with ",(0,h.jsx)(n.code,{children:"conda activate reads-to-variants"})," or ",(0,h.jsx)(n.code,{children:"conda activate file-formats"}),". Otherwise, follow ",(0,h.jsx)(n.a,{href:"/docs/from-reads-to-variants/setting-up#install-the-tools",children:"Install\nthe Tools"})," on that\npage. The files on this page take up about 250 MB."]}),"\n",(0,h.jsx)(n.h2,{id:"try-it",children:"Try It"}),"\n",(0,h.jsxs)(n.p,{children:["Make a folder, download the GENCODE annotation from ",(0,h.jsx)(n.a,{href:"/docs/genomic-file-formats/GTF-GFF3-files#try-it",children:"GTF/GFF3\nFiles"}),", and save its gene lines\nto a smaller file:"]}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-bash",children:"# Make a folder for this page and move into it\nmkdir ncrna && cd ncrna\n# Download the GTF file for GENCODE release 50\ncurl -fLO https://ftp.ebi.ac.uk/pub/databases/gencode/Gencode_human/release_50/gencode.v50.annotation.gtf.gz\n# Save the gene lines to their own file\ngunzip -c gencode.v50.annotation.gtf.gz | awk -F '\\t' '$3 == \"gene\"' > genes.gtf\n# Count the genes of each kind of RNA on this page, with protein-coding genes for comparison\ngrep -o 'gene_type \"[^\"]*\"' genes.gtf | grep -E '\"(protein_coding|lncRNA|miRNA|snRNA|snoRNA|rRNA|Mt_tRNA|Mt_rRNA)\"' | sort | uniq -c | sort -rn\n"})}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-text",children:'34866 gene_type "lncRNA"\n20107 gene_type "protein_coding"\n1901 gene_type "snRNA"\n1878 gene_type "miRNA"\n 985 gene_type "snoRNA"\n  47 gene_type "rRNA"\n  22 gene_type "Mt_tRNA"\n   2 gene_type "Mt_rRNA"\n'})}),"\n",(0,h.jsxs)(n.p,{children:["There are about 35,000 lncRNA genes, against about 20,000 protein-coding genes. Two\nkinds of RNA from this page are thin on the ground. The only tRNA genes here are the 22\nin the mitochondrial genome, because GENCODE keeps its predicted nuclear tRNA genes in a\nseparate file (",(0,h.jsx)(n.a,{href:"https://www.gencodegenes.org/human/release_50.html",children:"GENCODE release\n50"}),"). And none of the 47 rRNA genes\nis an 18S or 28S gene:"]}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-bash",children:"# Count the rRNA genes named 18S or 28S\ngrep 'gene_type \"rRNA\";' genes.gtf | grep -c '18S\\|28S'\n"})}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-text",children:"0\n"})}),"\n",(0,h.jsxs)(n.p,{children:["The 18S and 28S genes sit in long arrays of repeated copies, called rDNA, that the\nGRCh38 reference genome leaves as unknown sequence (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1126/science.abj6987",children:"Nurk et al.,\n2022"}),")."]}),"\n",(0,h.jsx)(n.p,{children:"Next, find the two microRNA genes from 13q14:"}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-bash",children:"# Show the position, strand and name of MIR15A, MIR16-1 and DLEU2\ngrep -E 'gene_name \"(MIR15A|MIR16-1|DLEU2)\";' genes.gtf | awk -F '\\t' '{split($9, a, \";\"); print $1, $4, $5, $7 a[3]}'\n"})}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-text",children:'chr13 49956669 50126118 - gene_name "DLEU2"\nchr13 50048973 50049061 - gene_name "MIR16-1"\nchr13 50049119 50049201 - gene_name "MIR15A"\n'})}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.em,{children:"MIR15A"})," and ",(0,h.jsx)(n.em,{children:"MIR16-1"})," sit about 60 bases apart, and both fall inside ",(0,h.jsx)(n.em,{children:"DLEU2"}),", a lncRNA\ngene, on the same strand. Each microRNA gene here is only 80 to 90 bases long, about the\nsize of the hairpin. To see their sequences, download chromosome 13 of the reference:"]}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-bash",children:"# Download chromosome 13 of GRCh38 from UCSC\ncurl -fLO https://hgdownload.soe.ucsc.edu/goldenPath/hg38/chromosomes/chr13.fa.gz\n# Decompress it to chr13.fa\ngunzip chr13.fa.gz\n# Index it so tools can jump to any position\nsamtools faidx chr13.fa\n# Read both hairpins on the - strand, each on one line\nsamtools faidx -i -n 100 chr13.fa chr13:50048973-50049061 chr13:50049119-50049201\n"})}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-text",children:">chr13:50048973-50049061/rc\nGTCAGCAGTGCCTTAGCAGCACGTAAATATTGGCGTTAAGATTCTAAAATTATCTCCAGTATTAACTGTGCTGCTGAAGTAAGGTTGAC\n>chr13:50049119-50049201/rc\nCCTTGGAGTAAAGTAGCAGCACATAATGGTTTGTGGATTTTGAAAAGGTGCAGGCCATATTGTGCTGCCTCAAAAATACAAGG\n"})}),"\n",(0,h.jsxs)(n.p,{children:["Both genes are on the ",(0,h.jsx)(n.code,{children:"-"})," strand, which means their RNA is copied from the opposite\nstrand to the one the reference spells out. The ",(0,h.jsx)(n.code,{children:"-i"})," option turns each region around and\nswaps every base for its partner, so you see the sequence the way the RNA reads, from 5\u2032\nto 3\u2032. ",(0,h.jsx)(n.a,{href:"/docs/advanced-topics/alternative-splicing#try-it",children:"Alternative Splicing"})," uses the same option. ",(0,h.jsx)(n.code,{children:"-n 100"})," keeps each sequence on one line. The reference is DNA, so it shows T where the RNA\nhas U."]}),"\n",(0,h.jsx)(n.p,{children:"Each sequence folds back on itself to form a hairpin, so stretches in its first half\npair with stretches in its second half. In the first hairpin, bases 15 to 22 read\nAGCAGCAC, and bases 68 to 75 read GTGCTGCT. Write the second stretch backward under the\nfirst, and every base lines up with its partner, A with T and G with C:"}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-text",children:"bases 15 to 22            5\u2032 AGCAGCAC 3\u2032\n                             ||||||||\nbases 68 to 75, backward  3\u2032 TCGTCGTG 5\u2032\n"})}),"\n",(0,h.jsxs)(n.p,{children:["As you'll see below, bases 15 to 22 are part of miR-16, and bases 68 to 75 are part of\nits partner strand, as in step 1 of ",(0,h.jsx)(n.a,{href:"#figure-7-7",children:"Figure 7.7"}),"."]}),"\n",(0,h.jsxs)(n.p,{children:["miRBase, a catalog of microRNAs, lists miR-16 as UAGCAGCACGUAAAUAUUGGCG (",(0,h.jsx)(n.a,{href:"https://www.mirbase.org/mature/MIMAT0000069",children:"miRBase\nMIMAT0000069"}),") and miR-15a as\nUAGCAGCACAUAAUGGUUUGUG (",(0,h.jsx)(n.a,{href:"https://www.mirbase.org/mature/MIMAT0000068",children:"miRBase\nMIMAT0000068"}),"). Each starts at the 14th\nbase of its hairpin. Read just those 22 bases:"]}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-bash",children:"# Read the mature miR-16 and miR-15a\nsamtools faidx -i chr13.fa chr13:50049027-50049048 chr13:50049167-50049188\n"})}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-text",children:">chr13:50049027-50049048/rc\nTAGCAGCACGTAAATATTGGCG\n>chr13:50049167-50049188/rc\nTAGCAGCACATAATGGTTTGTG\n"})}),"\n",(0,h.jsxs)(n.p,{children:["The two microRNAs differ after their ninth base, but they share their seed, AGCAGC at\npositions 2 to 7, so both belong to the miR-15/16 seed family and can pair with the same\nsites. The first is the miR-16 in ",(0,h.jsx)(n.a,{href:"#figure-7-7",children:"Figure 7.7"}),", where it's written\nbackward, from 3\u2032 to 5\u2032."]}),"\n",(0,h.jsx)(n.p,{children:"That's the end of this exercise. Move out of the folder and delete it:"}),"\n",(0,h.jsx)(n.pre,{children:(0,h.jsx)(n.code,{className:"language-bash",children:"# Move up out of the folder\ncd ..\n# Delete the folder and everything in it\nrm -r ncrna\n"})})]})}function f(e={}){const{wrapper:n}={...(0,d.R)(),...e.components};return n?(0,h.jsx)(n,{...e,children:(0,h.jsx)(p,{...e})}):p(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>r});var s=t(6540);const a={},i=s.createContext(a);function o(e){const n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);